"""Telegram notifications and channel monitoring UI."""


def telegram_html() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Telegram · 影舟 MovieArk</title><style>
:root{--line:#17515a;--gold:#d7b975;--cyan:#29cadc;--muted:#9b907b}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 75% 0,#2c2112,#080705 45%);color:#e6ddc8;font:14px system-ui,"Microsoft YaHei",sans-serif}.shell{display:grid;grid-template-columns:235px 1fr;min-height:100vh}.side{background:#080704ee;border-right:1px solid var(--line);padding:20px 12px}.logo{font-size:21px;font-weight:800;color:var(--gold);padding:6px 10px 28px}.nav{display:block;color:#b9a982;text-decoration:none;padding:13px 15px;border-radius:12px;font-weight:700}.nav:hover,.nav.active{background:#123a40;color:#45d8e8}.group{font-size:11px;color:#776d58;border-bottom:1px solid #3a311f;padding:16px 8px 7px;margin-bottom:5px}.top{height:64px;display:flex;align-items:center;padding:0 28px;border-bottom:1px solid var(--line);font-size:22px;font-weight:800;color:var(--cyan)}.save{margin-left:auto;background:#153a40;color:#58dcea;border:1px solid #26747d;border-radius:9px;padding:9px 16px}.wrap{max-width:1250px;margin:auto;padding:24px}.card{background:#12100b;border:1px solid var(--line);border-radius:15px;padding:20px;margin-bottom:16px}.card h2{color:var(--gold);margin-top:0}.hint{color:var(--muted);margin-bottom:15px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field label{display:block;color:#aa9c84;margin-bottom:6px}.field input,.field textarea{width:100%;border:1px solid #245d65;border-radius:8px;background:#080806;color:#ddd;padding:10px}.field input{height:43px}.field textarea{height:150px}.events{display:flex;flex-wrap:wrap;gap:12px;margin:12px 0}.event{padding:9px 12px;background:#17140e;border:1px solid #4d3d23;border-radius:9px}.actions{display:flex;gap:9px;margin-top:14px}.actions button{padding:9px 14px;border:1px solid #39777d;border-radius:8px;background:#15343a;color:#5bd8e6}.ch-actions{display:flex;gap:9px;flex-wrap:wrap;margin-top:14px}.ch-actions button,.modal-actions button{padding:9px 14px;border:1px solid #39777d;border-radius:8px;background:#15343a;color:#5bd8e6;cursor:pointer}.ch-actions button.primary,.modal-actions button.primary{background:#78551f;border-color:#a07836;color:#ffe0a0}.ch-actions button.danger{border-color:#8a3b42;background:#3a1d20;color:#ffb9be}.channel-list{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:16px}.channel{background:#0a0907;border:1px solid #3c331f;border-radius:12px;padding:14px}.channel .ch-head{display:flex;align-items:center;gap:10px;margin-bottom:8px}.channel .ch-head b{color:#e2c87f;font-size:15px}.ch-status{border-radius:12px;padding:3px 9px;font-size:12px}.ch-status.on{background:#173a29;color:#6be6a2}.ch-status.off{background:#3a201d;color:#ef8b8b}.ch-meta{color:#9d927e;font-size:12px;line-height:1.8}.ch-meta.err{color:#ffb9be}.channel .ch-actions{display:flex;gap:8px;margin-top:12px}.channel .ch-actions button{padding:7px 11px;font-size:12px}.empty{color:var(--muted);border:1px dashed #3c331f;border-radius:12px;padding:26px;text-align:center;margin-top:16px}.modal{display:none;position:fixed;inset:0;z-index:90;background:#000b;align-items:center;justify-content:center;padding:18px}.modal.show{display:flex}.modal-box{width:min(460px,100%);background:#15110c;border:1px solid #287680;border-radius:18px;padding:22px;box-shadow:0 25px 80px #000}.modal-box h3{color:var(--gold);margin:0 0 16px}.modal-actions{display:flex;gap:9px;margin-top:18px;justify-content:flex-end}.status{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-top:14px}.metric{background:#0a0907;border:1px solid #3c331f;border-radius:9px;padding:12px}.metric span{display:block;color:var(--muted);font-size:12px}.toast{display:none;position:fixed;right:24px;bottom:24px;padding:13px 17px;border:1px solid #48b67f;background:#15392d;border-radius:9px;color:#c9f6da}.toast.bad{background:#3b1e20;border-color:#b64e55;color:#ffd0d2}@media(max-width:850px){.shell{display:block}.side{display:none}.grid,.status{grid-template-columns:1fr}.wrap{padding:12px}}
</style></head><body><div class="shell"><aside class="side"><div class="logo">◉ 影舟 MovieArk</div><div class="group">发现</div><a class="nav" href="/rankings">🏆 榜单</a><a class="nav" href="/explore">◉ 汇影</a><a class="nav" href="/search">⌕ 搜索</a><div class="group">订阅</div><a class="nav" href="/subscriptions">☷ 订阅列表</a><a class="nav" href="/tasks">▣ 订阅任务</a><a class="nav" href="/unlocks">◴ 解锁记录</a><div class="group">系统</div><a class="nav" href="/authorizations">⌘ 授权中心</a><a class="nav" href="/settings">⚙ 业务设置</a><a class="nav active" href="/telegram">✈ Telegram</a><a class="nav" href="/logs">▤ 日志中心</a></aside><main><header class="top">✈ Telegram 通知与频道<button id="save" class="save">保存设置</button></header><section class="wrap"><article class="card"><h2>通知机器人</h2><div class="hint">敏感凭据只保存在服务端。可分别启用不同业务事件。</div><div class="grid"><div class="field"><label>Bot Token</label><input id="bot_token" type="password" placeholder="留空表示不修改"></div><div class="field"><label>Chat ID</label><input id="chat_id"></div><div class="field"><label>Telegram API ID</label><input id="api_id" placeholder="用于用户侧搜索授权（可选）"></div><div class="field"><label>API Hash</label><input id="api_hash" type="password" placeholder="留空表示不修改"></div><div class="field"><label>授权用户 ID</label><input id="authorized_user_id" placeholder="仅允许该用户控制机器人"></div></div><label class="event"><input type="checkbox" id="enabled"> 启用 Telegram 通知</label><div class="events" id="events"></div><div class="grid"><div class="field"><label>自定义模板</label><textarea id="template"></textarea></div><div class="field"><label>实时预览</label><textarea id="preview" readonly></textarea></div></div><div class="actions"><button id="test">测试发送</button></div></article><article class="card"><h2>影巢频道自动转存（多频道）</h2><div class="hint">支持多个 Telegram 频道独立监控与转存。频道只是监控输入源，凭据统一复用上方通知机器人的 Bot Token / API ID / API Hash。每个频道独立保存游标与检查时间，单频道失败不影响其他频道。</div><div class="ch-actions"><button id="addChannel" class="primary">＋ 添加频道</button><button id="checkAll">全部检查</button><button id="refresh">刷新状态</button></div><div id="channelList" class="channel-list"></div></article></section></main></div><div id="toast" class="toast"></div><div id="channelModal" class="modal"><div class="modal-box"><h3 id="chModalTitle">添加频道</h3><div class="field"><label>频道名称</label><input id="ch_name" placeholder="例如：影巢官方频道"></div><div class="field"><label>频道用户名 / 链接</label><input id="ch_username" placeholder="https://t.me/oneonefivewpfx 或 @oneonefivewpfx"></div><label class="event"><input type="checkbox" id="ch_enabled" checked> 启用频道</label><div class="field"><label>检查周期（秒，60-86400）</label><input id="ch_interval" type="number" min="60" max="86400" value="600"></div><div class="modal-actions"><button id="ch_save" class="primary">保存</button><button id="ch_cancel">取消</button></div></div></div><script>
const $=s=>document.querySelector(s),eventDefs={transfer_success:'转存成功',transfer_failed:'转存失败',subscription:'订阅事件',manual_review:'刮削/人工确认'};let cfg={},CHANNELS=[],editing=null;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=ts=>ts?new Date(ts*1000).toLocaleString('zh-CN',{hour12:false}):'尚未检查';function drawEvents(){ $('#events').innerHTML=Object.entries(eventDefs).map(([k,v])=>`<label class="event"><input data-event="${k}" type="checkbox" ${cfg.events?.[k]?'checked':''}> ${v}</label>`).join('')}function preview(){const v={title:'示例影片',status:'转存成功',resource:'影巢资源',resolution:'4K',size:'18.6 GB',save_path:'/影视/待整理',error:''};let t=$('#template').value||'【影舟 MovieArk】{title}\n状态：{status}\n资源：{resource}\n清晰度：{resolution}\n大小：{size}\n保存路径：{save_path}\n{error}';for(const[k,x]of Object.entries(v))t=t.replaceAll('{'+k+'}',x);$('#preview').value=t}async function load(){const r=await fetch('/api/web/telegram/settings'),d=await r.json();if(!r.ok)return toast(d.detail||'加载失败',true);cfg=d;$('#chat_id').value=d.chat_id||'';$('#enabled').checked=!!d.enabled;$('#template').value=d.template||'';drawEvents();preview();loadChannels()}async function save(){const events={};document.querySelectorAll('[data-event]').forEach(x=>events[x.dataset.event]=x.checked);const body={bot_token:$('#bot_token').value,chat_id:$('#chat_id').value,enabled:$('#enabled').checked,events,template:$('#template').value,channel_enabled:false,channel_name:'',channel_interval:600};const r=await fetch('/api/web/telegram/settings',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();toast(r.ok?'设置已保存':d.detail||'保存失败',!r.ok);if(r.ok)load()}async function loadChannels(){const r=await fetch('/api/web/telegram/channels'),d=await r.json();if(!r.ok)return toast(d.detail||'频道列表加载失败',true);CHANNELS=d.items||[];renderChannels()}function renderChannels(items){const el=$('#channelList');if(!items.length){el.innerHTML='<div class="empty">还没有频道，点击【＋ 添加频道】开始监控。</div>';return}el.innerHTML=items.map(c=>`<div class="channel"><div class="ch-head"><b>${esc(c.name)}</b><span class="ch-status ${c.enabled?'on':'off'}">${c.enabled?'已启用':'已禁用'}</span></div><div class="ch-meta">@${esc(c.username)} · 每 ${c.check_interval} 秒检查</div><div class="ch-meta">上次检查：${fmt(c.last_check_at)} · 下次检查：${fmt(c.next_check_at)}</div><div class="ch-meta ${c.last_error?'err':''}">最近状态：${esc(c.last_error||c.last_status||'等待运行')}</div><div class="ch-meta">累计处理：${c.processed_count||0}</div><div class="ch-actions"><button class="check" data-id="${c.id}">立即检查</button><button class="edit" data-id="${c.id}">编辑</button><button class="toggle" data-id="${c.id}">${c.enabled?'禁用':'启用'}</button><button class="del danger" data-id="${c.id}">删除</button></div></div>`).join('');el.querySelectorAll('.check').forEach(b=>b.onclick=()=>checkOne(+b.dataset.id));el.querySelectorAll('.edit').forEach(b=>b.onclick=()=>openModal(+b.dataset.id));el.querySelectorAll('.toggle').forEach(b=>b.onclick=()=>toggleOne(+b.dataset.id));el.querySelectorAll('.del').forEach(b=>b.onclick=()=>delOne(+b.dataset.id))}async function checkOne(id){const r=await fetch('/api/web/telegram/channels/'+id+'/check',{method:'POST'}),d=await r.json();toast(d.message||d.detail||'检查完成',!r.ok);loadChannels()}async function checkAll(){const r=await fetch('/api/web/telegram/channels/check',{method:'POST'}),d=await r.json();if(!r.ok)return toast(d.detail||'检查失败',true);toast((d.message||'全部检查完成')+'（共 '+d.checked+' 个频道）');loadChannels()}async function toggleOne(id){const c=CHANNELS.find(x=>x.id===id);if(!c)return;const r=await fetch('/api/web/telegram/channels/'+id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:c.name,username:c.username,enabled:!c.enabled,check_interval:c.check_interval})}),d=await r.json();toast(r.ok?'已更新频道状态':d.detail||'更新失败',!r.ok);loadChannels()}async function delOne(id){const c=CHANNELS.find(x=>x.id===id);if(!c)return;if(!confirm(`确认删除频道「${c.name}」的监控配置？历史解锁/转存记录会保留。`))return;const r=await fetch('/api/web/telegram/channels/'+id,{method:'DELETE'}),d=await r.json();toast(r.ok?'已删除频道':d.detail||'删除失败',!r.ok);loadChannels()}function openModal(id){const c=CHANNELS.find(x=>x.id===id);editing=c?c.id:null;$('#chModalTitle').textContent=c?'编辑频道':'添加频道';$('#ch_name').value=c?.name||'';$('#ch_username').value=c?('@'+c.username):'';$('#ch_enabled').checked=c?c.enabled:true;$('#ch_interval').value=c?.check_interval||600;$('#channelModal').classList.add('show')}function closeModal(){$('#channelModal').classList.remove('show');editing=null}async function saveChannel(){const name=$('#ch_name').value.trim(),username=$('#ch_username').value.trim(),enabled=$('#ch_enabled').checked,check_interval=Math.max(60,Math.min(86400,+$('#ch_interval').value||600));if(!username)return toast('请填写频道用户名或链接',true);const body={name,username,enabled,check_interval};const r=await fetch('/api/web/telegram/channels'+(editing?'/'+editing:''),{method:editing?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok)return toast(d.detail||'保存失败',true);toast(editing?'频道已更新':'频道已添加');closeModal();loadChannels()}function toast(m,b=false){const t=$('#toast');t.textContent=m;t.className='toast'+(b?' bad':'');t.style.display='block';setTimeout(()=>t.style.display='none',3500)}$('#save').onclick=save;$('#test').onclick=async()=>{const r=await fetch('/api/web/telegram/test',{method:'POST'}),d=await r.json();toast(d.message||d.detail||'操作完成',!r.ok)};$('#addChannel').onclick=()=>openModal(null);$('#checkAll').onclick=checkAll;$('#refresh').onclick=loadChannels;$('#ch_save').onclick=saveChannel;$('#ch_cancel').onclick=closeModal;$('#channelModal').onclick=e=>{if(e.target===$('#channelModal'))closeModal()};$('#template').oninput=preview;load();
</script></body></html>'''
